def P(text,style='Bodyx'): return Paragraph(text,styles[style])
def bullet(text): return Paragraph('• '+text,styles['Bulletx'])
def section(title): return [P(title,'H1x'),HRFlowable(width='100%',thickness=1.2,color=colors.HexColor(teal),spaceAfter=9)]
def table(data,widths,header=True):
    t=Table(data,colWidths=widths,repeatRows=1 if header else 0,hAlign='LEFT')
    cmds=[('VALIGN',(0,0),(-1,-1),'TOP'),('GRID',(0,0),(-1,-1),.35,colors.HexColor('#D6E0E7')),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5)]
    if header: cmds += [('BACKGROUND',(0,0),(-1,0),colors.HexColor(navy)),('TEXTCOLOR',(0,0),(-1,0),colors.white)]
    for r in range(1 if header else 0,len(data)):
        if r%2==0: cmds.append(('BACKGROUND',(0,r),(-1,r),colors.HexColor('#F3F7F9')))
    t.setStyle(TableStyle(cmds)); return t

def img(name,w=165*mm): return Image(str(TMP/name),width=w,height=w*0.39,kind='proportional')

def footer(canvas,doc):
    canvas.saveState(); W,H=A4
    if doc.page>1:
        canvas.setStrokeColor(colors.HexColor('#DCE5EB')); canvas.line(18*mm,H-14*mm,W-18*mm,H-14*mm)
        canvas.setFont('Arial',7.5); canvas.setFillColor(colors.HexColor(muted)); canvas.drawString(18*mm,H-11*mm,'SEGMENTATION DE CLIENTS | RAPPORT TECHNIQUE')
        canvas.setStrokeColor(colors.HexColor('#DCE5EB')); canvas.line(18*mm,14*mm,W-18*mm,14*mm)
        canvas.drawString(18*mm,9*mm,'Étude de cas académique - version du 22 octobre 2026')
        canvas.drawRightString(W-18*mm,9*mm,f'{doc.page}')
    canvas.restoreState()

