story += [P('Commandes documentées pour Windows','H2x'),P('<font name="Arial">python -m venv .venv<br/>.venv\\Scripts\\Activate.ps1<br/>python -m pip install -r requirements.txt</font>','Callout'),P('Réentraîner et recalculer les diagnostics','H2x'),P('<font name="Arial">python -m customer_segmentation.pipeline --data data/marketing_campaign.csv --k-min 2 --k-max 9 --seed 42</font>','Callout'),P('Lancer l’interface de démonstration','H2x'),P('<font name="Arial">streamlit run app/dashboard.py</font>','Callout'),P('Parcours conseillé durant la soutenance','H2x'),bullet('Commencer par l’objectif métier et les limites de la source.'),bullet('Présenter l’audit, puis défendre chaque variable et chaque exclusion.'),bullet('Expliquer comment l’imputation, le log et la standardisation répondent aux distributions observées.'),bullet('Montrer les courbes multi-métriques et l’arbitrage entre séparation et stabilité.'),bullet('Interpréter les profils en unités d’origine; séparer observation et causalité.'),bullet('Faire une démo d’affectation de clients nouveaux, puis conclure sur les validations nécessaires.'),P('Questions probables du jury','H2x'),bullet('<b>Pourquoi K-Means ?</b> Référence simple et interprétable sur variables numériques standardisées; il suppose des groupes relativement compacts et reste sensible à la géométrie et aux variables choisies.'),bullet('<b>Pourquoi K=2 alors que K=3 est plus stable ?</b> La règle annoncée privilégie la meilleure silhouette parmi les K dépassant le seuil de stabilité. K=3 peut être proposé comme alternative si la granularité métier le justifie.'),bullet('<b>Les résultats sont-ils généralisables ?</b> Non démontré : ce CSV ancien et d’origine exacte non vérifiée ne permet pas de garantir une performance hors échantillon.'),bullet('<b>Le cluster prédit-il une réponse marketing ?</b> Non. Le clustering ne prédit pas la réponse; elle est seulement décrite après coup.'),PageBreak()]
# Recommendations
story += section('8. Limites, risques et plan de progression')
limits=[[P('Priorité','CellBold'),P('Action recommandée','CellBold'),P('Résultat attendu','CellBold')],[P('1 - Données','CellBold'),P('Obtenir une base récente, autorisée et représentative; confirmer dictionnaire, unités, période et population.','Cell'),P('Validité externe et contexte métier documentés.','Cell')],[P('2 - Validation','CellBold'),P('Valider par fenêtres temporelles; réajuster tout le pipeline dans chaque réplication; tester plusieurs graines et bootstrap.','Cell'),P('Mesure de robustesse moins dépendante d’un seul split.','Cell')],[P('3 - Comparaison','CellBold'),P('Comparer à des baselines (K-Means sans log, GMM, clustering hiérarchique, HDBSCAN selon densité) et mesurer l’effet des variables.','Cell'),P('Choix d’algorithme et de représentation défendable.','Cell')],[P('4 - Utilité métier','CellBold'),P('Ateliers d’interprétation, stabilité des profils, actionnabilité et expérimentation contrôlée des campagnes.','Cell'),P('Passage de la segmentation descriptive à une valeur démontrée.','Cell')],[P('5 - Industrialisation','CellBold'),P('Tests unitaires et intégration, verrouillage des versions, API ou batch, monitoring de dérive, versionnage et plan de réentraînement.','Cell'),P('Pipeline exploitable et maintenable.','Cell')],[P('6 - Gouvernance','CellBold'),P('Documenter la licence, minimiser les données personnelles, étudier biais et impacts des usages de ciblage.','Cell'),P('Usage responsable et conformité mieux maîtrisés.','Cell')]]
story += [table(limits,[27*mm,81*mm,54*mm]),P('Évaluation honnête du niveau actuel','H2x'),P('Le projet est déjà plus qu’un notebook de clustering : il a un pipeline réutilisable, une séparation des champs de campagne, des métriques complémentaires, une stabilité estimée et un dashboard. Pour atteindre une démonstration de niveau ingénieur IA convaincante, l’argumentation doit insister sur les hypothèses et les limites. La principale amélioration scientifique est de vérifier la stabilité avec des pipelines complètement réajustés sur des périodes de données séparées et de confirmer la valeur des groupes avec des experts métier.','Bodyx'),P('Formulation recommandée en soutenance','H2x'),P('« Sur le jeu de cas disponible, K=2 offre le meilleur compromis selon notre règle annoncée : silhouette 0,346 et ARI de stabilité 0,966. Les deux segments diffèrent fortement en dépenses moyennes, et présentent des taux de réponse différents après clustering. Ces résultats décrivent ce fichier et ne prouvent ni représentativité, ni causalité, ni uplift marketing. La prochaine étape est une validation sur données récentes, temporelles et autorisées, avec expérimentation métier. »','Callout'),PageBreak()]
# Appendix
story += section('Annexe A. Définitions et inventaire des livrables')
terms=[('K-Means','Algorithme partitionnant les observations en K groupes autour de centroïdes en minimisant les distances quadratiques dans l’espace transformé.'),('Silhouette','Mesure de cohésion et de séparation entre -1 et 1; une valeur plus haute est généralement préférable.'),('ARI','Adjusted Rand Index : comparaison de partitions en corrigeant l’accord aléatoire; 1 signifie partitions identiques.'),('Inertie','Somme des distances quadratiques aux centroïdes; diminue souvent avec K et n’est pas comparable à elle seule.'),('Davies-Bouldin','Indice combinant dispersion intragroupe et distance entre groupes; plus faible est généralement préférable.'),('Calinski-Harabasz','Rapport dispersion intergroupes / intragroupes; plus élevé est généralement préférable.'),('Fuite de cible','Utilisation indirecte d’une information de résultat pour construire un modèle censé expliquer ou prédire ce résultat.')]
for term,desc in terms: story += [P(term,'H2x'),P(desc,'Bodyx')]
story += [P('Fichiers du dépôt examinés','H2x'),bullet('README.md : objectif, jeu de données, commandes, parcours de soutenance et limites.'),bullet('src/customer_segmentation/pipeline.py : transformations, entraînement, métriques et exports.'),bullet('models/kmeans_meta.json et outputs/comparaison_k.csv : chiffres consignés pour le run étudié.'),bullet('docs/model_card.md : usages attendus, usages exclus et validations à mener.'),bullet('app/dashboard.py et notebook/kmeans_segmentation.ipynb : interface et analyse exploratoire.'),Spacer(1,5*mm),P('La sortie PDF est placée dans le dossier parent du projet afin de respecter la demande de ne pas la ranger dans le dossier du projet.','Smallx')]
